"""Source-linked pending feat interfaces; existing flags are not current approval."""
from pathlib import Path
from collections import Counter
import json,hashlib,re
ROOT=Path(__file__).resolve().parents[1];GAME=ROOT.parents[1];AUDIT=GAME/'docs/audit/2026-10-08/full-game'
PATTERNS={'crafting':r'\b(?:craft\w*|artisan\w*|tools?|research\w*|engineering|masterwork)\b','language':r'\b(?:language\w*|linguist\w*)\b','materials':r'\b(?:material components?|gold|coins?|purchas\w*|sell\w*|salvag\w*|harvest\w*|repair\w*)\b'}
EXTRA={'skill_expert','jack_of_all_trades'}
QUESTIONS={
 'arcaneFocus':('Spell materials and Scribing activation','Define less-than100gp,consumed versus nonconsumed components,actual focus use/hands,spell eligibility and any interaction with stored spells. Preserve the full description/effect; never apply a spell-component exception to crafting ingredients automatically.'),
 'artisan':('Artisan credential and Masterwork wording','Choose the actual artisan tool,trade initialization and duplicate-training behavior. Decide what can create masterwork items authorizes against the quality table,formula/access and gear-grade rules; it need not mean automatic Masterwork outcome.'),
 'bowyer':('Bow/arrows,physical grade and flat damage','Define the bow-making credential/formula/station and Masterwork meaning,alongside its separate+1 bow-attack damage. Resolve arrows versus bow output and existing weapon bonus families,critical hits and prerequisite weapon proficiency without erasing either clause.'),
 'burglar':('Thieves tools and trap interaction','Bind the tool proficiency and more-effectively clause to actual lock/trap procedures. Decide whether any additional numeric or action benefit exists; do not turn it into permission to disarm every magical rune/device.'),
 'craftsman':('Half-time creation and other reductions','Define craft-items scope,chosen tool(s),trade initialization and half-normal-time interaction with Forge Dwarf,fractional minutes,assistant hours and first phases. Distinguish creation from research,repair,harvest,training and servicing; source scope must be decided explicitly.'),
 'diligent_researcher':('Research time and actual access','Define ordinary research,required library/archive/facility,active hours,task batching and combination with Scribing research aids. Preserve the explicit access/language/material restrictions; do not make a shorter research clock generate unavailable information or formulas.'),
 'forge':('Percentage durability and fire defense','Resolve all crafted armor+10% durability and resist fire by+10% against structural HP,craft workmanship,equipment grade and existing resistance. Define actor/output scope,rounding,selection,source prerequisite and whether an explicit new defense layer is needed; do not silently replace10% with normal resistance.'),
 'herbalist':('Rest-time salve and recipe access','Bind herbalism proficiency,the Nature5+ prerequisite,actual supplies,one healing-salve output,activation and1d6+PB. Resolve Long Rest activity exception,expiry after24hours,stacking,reserve/value and whether the salve is distinct from reviewed Herbalism formulas.'),
 'jack_of_all_trades':('Two untrained skill slots','Preserve the full current clause and legacyEffect. Define selection,half-PB floor,loss/retargeting after gaining proficiency and skill versus tool boundaries. It cannot be assumed to establish a trade credential or grant a second PB contribution.'),
 'linguist':('Three languages and ancient-language gates','Preserve all description/effect clauses and define legal language selections,duplicate choices,fluency and any source limits. Resolve relation to Language Insight and texts without automatically granting every ancient/hidden language.'),
 'merchant_s_guile':('Negotiated prices and finite buyers','Define ordinary goods,relevant Profession/check DC/action,up-to10% direction and timing,stacking,minimum/maximum quotes,rounding and repeated negotiations. Preserve fixed tariffs/monopolies; no guaranteed market,arbitrage or automatic artifact-price modifier.'),
 'polyglot':('Languages and related-script advantage','Define the three language choices,related dialect/script scope,identification versus fluency and actual check timing. Combine with Scribing references and Language Insight without converting identification advantage into automatic translation.'),
 'prodigy':('Mixed grants and ancestry prerequisite','Map the literal Half-elf/half-orc/human requirement to current ancestry identities with actual evidence. Preserve skill,tool,language andexpertise grants; define duplicate choices and artisan versus any-tool scope. No ancestry/cosmology expansion is inferred.'),
 'quick_learner':('Specific30-day training route','Define day/active-hour requirements,instructor/facility/cost,one use per category,eligible languages/tools and trade initialization. Reconcile with the reviewed80-active-hour ordinary trade route,which already defers to a named specific source; do not erase either time statement.'),
 'skill_expert':('Skill expertise and tool double-counting','Specify skill proficiency/expertise choices,already-proficient requirement,order,duplicate expertise and later changes. A skill expertise grant is not automatic expertise in an associated crafting tool or a second proficiency bonus on one roll.'),
 'skilled':('Three skills/tools and starting choices','Specify distinct choices,eligible tool credentials,duplicate grants,trade level1 initialization and class/background interactions. Preserve any combination of three; distinguish broad tool choices from an artisan-only grant.'),
 'tinker_adept':('Complex repairs and extra durability','Define Tinkering5+ against the actual trade-level credential,+2 eligible checks,short-rest repair compatibility and additional durability equalPB. Decide current-HP restoration versus maximum-HP increase,caps,materials and once-per-repair behavior; avoid repeatable free permanent HP.'),
 'versatile_artisan':('One additional discipline','Define discipline selection,primary-tool proficiency,trade level,formula/access,knowledge and prerequisites. Decide whether the source grants only cross-discipline use or a new trained credential; owning another kit cannot answer the question.'),
 'combat_engineering':('Fortifications,siege checks and kill-zone','Define construction baselines,half-time,+2 versus+1 emplaced-cover AC,Engineering checks,10foot kill-zone build/activation/one-short-rest budget,DC,damage type and first-hostile event. Reconcile with normal cover and Tinkering traps without dropping its non-trap clauses.'),
 'core_infusion':('Temporary imprints and personal crafting identity','Define the Long Rest infusion,one personally crafted weapon/armor,minor-property menu,24hour duration,Relic materials/forge and overwrite/removal. Separately resolve+2 repair and one-short-rest Craft reroll,eligibility,timing and interaction with permanent reviewed enhancements.'),
 'hardened_grip':('Disarm,size,craft bonus and attack timing','Resolve the no-disarm rule/reflected1d4,consciousness,actual weapons,hands,+2 Craft(Blacksmith),larger weapon use and full bonus-action grip lock. Preserve the movement condition,opportunity-attack disadvantage,+1d6 and duration; no blanket Strongest rule erases unrelated clauses.'),
 'master_smithing':('Masterwork,minor properties and weekly temper','Resolve original Craft(Blacksmith) credential,recipe/forge/material access,armor check penalty-1,fire resistance5 or other minor-property examples,+1 weapon damage and weekly named trait. Give finite flaming/returning/spell-holding procedures or explicit outstanding decisions; do not treat their names as complete mechanics.'),
 'siege_savant':('Percent damage,blast radius and structure actions','Resolve+20% target-specific damage/rounding,explosive radius+5feet,half-cover save bypass,weak-point check/next-attack advantage and studied5foot wall collapse. Bind Tinkering siege/traps,actual structure defenses,actions and short-rest budget; no unsupported exemption for magical/unique barriers.'),
 'trapsetter':('Fast placement and trap-specific budget','Define the three listed mechanical trap types,physical supplies,bonus action,once per short rest per type,save DC,effect choice/duration and detection advantage. Preserve reaction movement after triggering,range/line of sight,cover and no-opportunity-attack scope; do not equate every Rune/Tinkering formula with one of these types.')}
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def digest(x):return hashlib.sha256(json.dumps(x,sort_keys=True,ensure_ascii=False).encode()).hexdigest()
def create(p,s):
    with p.open('x',encoding='utf-8',newline='\n') as f:f.write(s)
def main():
    out=AUDIT/'CRAFTING_FEAT_INTERFACE_PREPARATION.json';notes=AUDIT/'CRAFTING_FEAT_INTERFACE_AUDIT.md';packet=AUDIT/'CODEX_CRAFTING_FEAT_INTERFACE_PREPARED.txt';assert not out.exists() and not notes.exists() and not packet.exists()
    source_path=ROOT/'src/data/feats.js';source=json.JSONDecoder().raw_decode(source_path.read_text(encoding='utf-8').split('export const feats = ',1)[1])[0];by={r['id']:r for r in source}
    catalog_path=ROOT/'data/public/feat_playtests/catalog.json';catalog=read(catalog_path);cb={r['id']:r for r in catalog['feats']};manifest_path=ROOT/'data/public/feat_playtests/manifest.json';manifest=read(manifest_path)
    pending=read(AUDIT/'REMAINING_FEAT_CATALOG_PREPARATION.json');pending_by={r['id']:r for r in pending['records']};matches=[]
    for r in source:
        hits=[]
        for field in ['description','effect','prerequisite']:
            for label,pattern in PATTERNS.items():
                hits += [{'category':label,'field':field,'span':[m.start(),m.end()],'exactText':m.group()} for m in re.finditer(pattern,str(r.get(field,'')),re.I)]
        if hits or r['id'] in EXTRA:matches.append({'featId':r['id'],'sourceObject':r,'sourceObjectSha256':digest(r),'matches':hits,'curatedExpertiseInterface':r['id'] in EXTRA,'currentOperationalStatus':cb[r['id']]['operationalStatus'],'issue':{'topic':QUESTIONS[r['id']][0],'question':QUESTIONS[r['id']][1]}})
    checks=[]
    def check(name,ok):checks.append({'name':name,'pass':bool(ok)})
    check('Both complete335-ID feat registries remain byte-identical',len(source)==len(by)==335 and source_path.read_bytes()==(GAME/'src/data/feats.js').read_bytes())
    check('All335 current catalog original objects equal source',set(cb)==set(by) and all(cb[id]['sourceObject']==r and cb[id]['sourceObjectSha256']==digest(r) for id,r in by.items()))
    check('Prepared327 pending originals still equal authoritative registry',pending['sourceFileSha256']==sha(source_path) and len(pending_by)==327 and all(r['sourceObject']==by[id] for id,r in pending_by.items()))
    check('Exactly24 selected matches and explicit expertise interfaces',len(matches)==24 and {m['featId'] for m in matches}==set(QUESTIONS))
    check('All24 pending and disjoint from eight reviewed feats',manifest['operationalFeats']==8 and manifest['unfinishedFeats']==327 and all(m['featId'] in pending_by and m['featId'] not in manifest['operationalIds'] and m['currentOperationalStatus']=='full-feat-review-pending' for m in matches))
    check('Every matched clause has exact source-span evidence',all(m['sourceObject'][hit['field']][slice(*hit['span'])]==hit['exactText'] for m in matches for hit in m['matches']))
    check('All24 full originals and legacy fields retained',all(m['sourceObject']==by[m['featId']] and digest(m['sourceObject'])==m['sourceObjectSha256'] for m in matches))
    guide_specs={'docs/mechanics/CRAFTING_HARVEST_PLAYTEST.md':['Training and recipe access','The crafting check','Active time and expedition scheduling','Quality and finite output','Salvage, research and sale'],'docs/mechanics/EQUIPMENT_ACQUISITION_PLAYTEST.md':['Hands and focuses','Equipment grade','Repair','Purchase and sale'],'docs/mechanics/CHARACTER_CREATION_PLAYTEST.md':['Abilities and training','Gain a level']}
    # Use exact heading spans. Do not silently match approximate section titles.
    boundaries=[]
    for rel,headings in guide_specs.items():
        p=ROOT/rel;s=p.read_text(encoding='utf-8');available=[m.group(1) for m in re.finditer(r'^## (.+)$',s,re.M)]
        for heading in headings:
            if heading not in available:raise ValueError((rel,heading,available))
            start=s.index('## '+heading+'\n');end=s.find('\n## ',start+1);section=s[start:end if end>=0 else len(s)]
            boundaries.append({'file':p.relative_to(GAME).as_posix(),'sha256':sha(p),'heading':heading,'exactSection':section})
    check('Exact reviewed sections retained with current hashes',len(boundaries)==11 and all(b['exactSection'] in (GAME/b['file']).read_text(encoding='utf-8') for b in boundaries))
    protected=dict(read(AUDIT/'TAILORING_PART2_REVIEW_BASELINE.json')['files'])
    for p in [source_path,GAME/'src/data/feats.js',catalog_path,manifest_path,ROOT/'docs/mechanics/BUFFER_FEAT_PLAYTEST.md',ROOT/'docs/mechanics/BUFFER_FEAT_PLAYTEST_VALIDATION.json',ROOT/'docs/mechanics/BUFFER_FEAT_SOURCE_VALIDATION.json',AUDIT/'GPT_BUFFER_FEAT_FINAL_CLOSURE.md',AUDIT/'REMAINING_FEAT_CATALOG_PREPARATION.json',AUDIT/'FEAT_IDENTITY_CANDIDATES.json']:
        protected[p.relative_to(GAME).as_posix()]=sha(p)
    check('Existing53 protected inputs remain unchanged',all(sha(GAME/p)==h for p,h in read(AUDIT/'TAILORING_PART2_REVIEW_BASELINE.json')['files'].items()))
    check('No selected source record merged or promoted',len({m['featId'] for m in matches})==24 and all(m['currentOperationalStatus']=='full-feat-review-pending' for m in matches))
    assert all(c['pass'] for c in checks),[c['name'] for c in checks if not c['pass']]
    evidence={'status':'Prepared source/interface evidence; not sent; no feat or crafting rule changed','sourceFile':source_path.relative_to(GAME).as_posix(),'sourceFileSha256':sha(source_path),'selectionScope':'All exact keyword hits for the saved patterns across335 description/effect/prerequisite fields, plus Skill Expert and Jack of All Trades. This is a focused craft/research/language/material interface selection, not a complete interpretation of all335 feats.','patterns':PATTERNS,'curatedExtraIds':sorted(EXTRA),'selectedFeats':matches,'reviewedBoundarySections':boundaries,'counts':{'sourceFeats':335,'alreadyReviewed':8,'remainingFullReviews':327,'selectedPending':24},'historicalIdentityAudit':{'file':'docs/audit/2026-10-08/full-game/FEAT_IDENTITY_CANDIDATES.json','sha256':sha(AUDIT/'FEAT_IDENTITY_CANDIDATES.json'),'scope':'Names remain separate identities; related-name candidates are not merges or stacking decisions.'},'checks':checks,'protectedFiles':protected,'featsApproved':0,'recipesApproved':0,'sourceInformationDeleted':0,'cosmology':'Deferred until successful authorized push and verified remote commit.'}
    create(out,json.dumps(evidence,ensure_ascii=False,indent=2)+'\n')
    text=['# Crafting, research and language feat interfaces','',f'Internal source preparation only. All335 feat originals and the327 pending records still match their registry. This focused audit selects24 pending feats; {len(checks)} checks pass. None of the24 is among the eight reviewed full-feat cards. Historical draft:false or needsReview:false flags do not approve these interfaces.','',
      'The complete original description,effect,prerequisite,type,legacyEffect andother fields remain in the evidence. Every automated selection has exact field/span text; Skill Expert andJack of All Trades are additional explicit expertise interfaces. This is not an exhaustive mechanical review of all335 feats.','',
      '| Pending feat | Interface to settle with GPT |','|---|---|']
    for m in matches:text.append('| '+m['sourceObject']['name']+' | '+m['issue']['question'].replace('|','/')+' |')
    text +=['','Existing crafting/equipment/character sections are supplied verbatim as governing context. Their historical checkpoint labels remain historical: later reviewed recipe manifests control current effect approvals. No rule in this audit makes an unfinished feat usable,changes a previously reviewed item or resolves a source conflict.','',
      'Once the current Tailoring request completes, schedule this focused conference within the wider feat/crafting integration work. A future dispatch must carry the then-current reviewed rules and complete sources; no new message has been sent. Preserve all eight reviewed feats andtheir separate class/spell interfaces. Exact full-clause feat cards,including non-crafting clauses,must receive their own review.','',
      '[Complete source and clause evidence](CRAFTING_FEAT_INTERFACE_PREPARATION.json). Final flow,runtime,human balance and ingredient availability remain open. No deletion,push or cosmology review occurred.','']
    create(notes,'\n'.join(text))
    prompt='PREPARED CRAFTING/RESEARCH/LANGUAGE FEAT INTERFACE EVIDENCE — NOT SENT. No decisions or approval. Do not interrupt the active Tailoring request. Before a future conference verify current rules,retain all originals and request finite directions for the complete selected feats,not only their crafting phrases.\n\n'+notes.read_text(encoding='utf-8')+'\n\nCOMPLETE SOURCE EVIDENCE\n'+json.dumps({k:v for k,v in evidence.items() if k!='protectedFiles'},ensure_ascii=False,separators=(',',':'))+'\n\nNo individual feat is promoted by this preparation.\n'
    create(packet,prompt)
    create(AUDIT/'CRAFTING_FEAT_INTERFACE_STATUS.json',json.dumps({'status':'Prepared-not-sent;24 pending feats,zero approvals','packetFile':packet.name,'characters':len(prompt),'sha256':sha(packet),'checks':len(checks),'protectedFiles':len(protected),'allSourceFeats':335,'selectedFeats':24,'reviewedFeatsUnchanged':8,'remainingFeats':327,'recipesReviewedUnchanged':262,'featsApproved':0,'recipesApproved':0},ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'status':'PASS','selectedFeats':24,'sourceFeatsPreserved':335,'checks':len(checks),'protectedFiles':len(protected),'packetCharacters':len(prompt),'featsApproved':0}))
if __name__=='__main__':main()
